:root { --slidev-theme-primary: #65e6c4; }
.slidev-layout { background: #101b2c; color: #edf4ff; padding: 48px 60px; }
.slidev-layout h1 { font-size: 48px; font-weight: 720; line-height: 1.12; margin: 20px 0 22px; letter-spacing: -1.8px; }
.slidev-layout p { margin: 0; }
.eyebrow { color: #65e6c4; letter-spacing: 3px; font-size: 14px; font-weight: 700; }
.lead { font-size: 25px; color: #c4d4e9; margin: 16px 0 24px; }
.slidev-layout pre, .slidev-layout code { font-family: 'DejaVu Sans Mono', monospace !important; font-size: 15px !important; line-height: 1.8 !important; }
.slidev-layout pre { padding: 20px !important; border: 1px solid #30445d; border-radius: 12px; }
