.stub { position: absolute; bottom: 26px; font-size: 13px; letter-spacing: 1.4px; color: #91a3bb; }
.diagram { height: 275px; overflow: hidden; border-radius: 12px; margin: 0 0 16px; background: #f4f8fb; }
.diagram img { width: 1160px; max-width: none; margin-top: -157px; }
